// Reads the two source CSVs in data/ and writes data/foods.json, data/mets.json,
// and data/verification.md. Run with: node scripts/build_data.js
// Every value in the generated files is copied from the CSV rows, never invented.

const fs = require("fs");
const path = require("path");

const DATA_DIR = path.join(__dirname, "..", "data");
const FOODS_CSV = path.join(DATA_DIR, "sg_meals_yeo2021.csv");
const METS_CSV = path.join(DATA_DIR, "compendium_adult_sample.csv");

// Minimal RFC4180 CSV parser: handles quoted fields with embedded commas.
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  const lines = text.replace(/\r\n/g, "\n");
  for (let i = 0; i < lines.length; i++) {
    const c = lines[i];
    if (inQuotes) {
      if (c === '"') {
        if (lines[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === "\n") {
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else {
      field += c;
    }
  }
  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows.filter((r) => r.length > 1 || (r.length === 1 && r[0] !== ""));
}

function readCsvRows(filePath) {
  const text = fs.readFileSync(filePath, "utf8");
  const rows = parseCsv(text);
  const header = rows[0];
  return rows.slice(1).map((r, idx) => {
    const obj = { __sourceRow: idx + 2 }; // +2: header is row 1, data starts at row 2
    header.forEach((h, i) => (obj[h] = r[i] !== undefined ? r[i] : ""));
    return obj;
  });
}

function slugify(name, used) {
  let base = name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
  let id = base;
  let n = 2;
  while (used.has(id)) {
    id = `${base}-${n}`;
    n++;
  }
  used.add(id);
  return id;
}

// The Yeo et al. (2021) paper presents Singapore hawker meals in three tables
// grouped by ethnic cuisine. Table 1 = Chinese dishes, Table 2 = Malay dishes,
// Table 3 = Indian dishes, matching every dish name in each table of this file.
const TABLE_TO_CATEGORY = {
  "Table 1": "Chinese",
  "Table 2": "Malay",
  "Table 3": "Indian",
};

function buildFoods() {
  const rows = readCsvRows(FOODS_CSV);
  const used = new Set();
  const foods = rows.map((r) => {
    const category = TABLE_TO_CATEGORY[r.source_table.trim()] || r.source_table.trim();
    return {
      id: slugify(r.food_name, used),
      name: r.food_name,
      category,
      source: "Yeo et al. (2021), Foods 10(7):1659",
      source_file: "sg_meals_yeo2021.csv",
      source_row: r.__sourceRow,
      per100g: {
        kcal: Number(r.kcal),
        protein_g: Number(r.protein_g),
        carbs_g: Number(r.carbs_g),
        fat_g: Number(r.fat_g),
      },
      verified: true,
      retrieved: r.retrieved_date,
    };
  });
  return foods;
}

// Activity category derived only from keywords already present in the
// activity text in the CSV (no external categorization data used).
const CATEGORY_RULES = [
  [/walking/i, "Walking"],
  [/running|jogging/i, "Running & Jogging"],
  [/bicycling/i, "Bicycling"],
  [/swimming/i, "Swimming"],
  [/yoga/i, "Yoga"],
  [/resistance \(weight\) training/i, "Resistance Training"],
  [/rope (jumping|skipping)|jumping rope/i, "Rope Jumping"],
  [/stair climbing/i, "Stair Climbing"],
  [/circuit training/i, "Circuit Training"],
  [/calisthenics/i, "Calisthenics"],
];

function categorize(activity) {
  for (const [re, label] of CATEGORY_RULES) {
    if (re.test(activity)) return label;
  }
  return "Other";
}

function buildMets() {
  const rows = readCsvRows(METS_CSV);
  const kept = rows.filter((r) => r.rounding_check.trim().toLowerCase() !== "fail");
  return kept.map((r) => ({
    code: r.code,
    name: r.activity,
    category: categorize(r.activity),
    met: Number(r.met),
    source: "2024 Adult Compendium of Physical Activities, J Sport Health Sci 2024;13(1):6-12",
    source_file: "compendium_adult_sample.csv",
    verified: false,
    verification_status: r.verification_status.trim(),
  }));
}

function buildVerificationMd(foods, mets) {
  const lines = [
    "# Data verification log",
    "",
    "Generated by scripts/build_data.js. One row per item copied into foods.json or mets.json.",
    "",
    "| Item type | Name / code | Source file | Source row | Verified | Confidence (1-10) |",
    "|---|---|---|---|---|---|",
  ];
  foods.forEach((f) => {
    lines.push(`| Food | ${f.name} | ${f.source_file} | ${f.source_row} | ${f.verified} | 7 |`);
  });
  mets.forEach((m) => {
    lines.push(`| Workout | ${m.name} (${m.code}) | ${m.source_file} | — | ${m.verified} | 6 |`);
  });
  lines.push("");
  lines.push(
    "Confidence rules: Yeo food row copied from the file = 7. Compendium workout row copied from the file, rounding check passed, not checked against the published PDF = 6. Custom or user-entered items (added inside the app) are not rated and do not appear in this file."
  );
  return lines.join("\n");
}

function main() {
  const foods = buildFoods();
  const mets = buildMets();
  fs.writeFileSync(path.join(DATA_DIR, "foods.json"), JSON.stringify(foods, null, 2) + "\n");
  fs.writeFileSync(path.join(DATA_DIR, "mets.json"), JSON.stringify(mets, null, 2) + "\n");
  fs.writeFileSync(path.join(DATA_DIR, "verification.md"), buildVerificationMd(foods, mets) + "\n");
  console.log(`Wrote ${foods.length} foods, ${mets.length} workouts.`);
}

main();
